import{_ as t,o as r,c as n,a5 as f}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"，unref","description":"在 Vue 3 中，unref 是一个 ​​响应式工具函数​​，用于处理 ​​ref​​ 和 ​​普通值​​，使其在代码中更灵活地使用。它是 @vue/reactivity 或 @vue/runtime core 提供的一个实用方法。 ​​1. unref 的作用​​ unref。","frontmatter":{"title":"，unref","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","模板、组件与交互"],"description":"在 Vue 3 中，unref 是一个 ​​响应式工具函数​​，用于处理 ​​ref​​ 和 ​​普通值​​，使其在代码中更灵活地使用。它是 @vue/reactivity 或 @vue/runtime core 提供的一个实用方法。 ​​1. unref 的作用​​ unref。","sidebarWeight":65,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/api/，unref.md"},"headers":[],"relativePath":"posts/Vue系统教程/02-模板、组件与交互/，unref.md","filePath":"posts/Vue系统教程/02-模板、组件与交互/，unref.md"}'),u={name:"posts/Vue系统教程/02-模板、组件与交互/，unref.md"};function a(o,e,p,c,i,s){return r(),n("div",null,[...e[0]||(e[0]=[f('<div><h1 id="unref" tabindex="-1">，unref <a class="header-anchor" href="#unref" aria-label="Permalink to &quot;，unref&quot;">​</a></h1><blockquote><p>本节目标：理解“，unref”的核心思路，并能把它用于实际开发或面试表达。 在 Vue 3 中，unref 是一个 ​​响应式工具函数​​，用于处理 ​​ref​​ 和 ​​普通值​​，使其在代码中更灵活地使用。它是 @vue/reactivity 或 @vue/runtime-core 提供的一个实用方法。</p></blockquote><p>​​1. unref 的作用​​ unref 的作用是 ​​安全地获取一个值​​，无论它是 ​​ref 对象​​ 还是 ​​普通值​​：</p><ul><li>如果传入的是 ref，则返回 ref.value（即解包 ref）。</li><li>如果传入的是普通值，则直接返回该值。</li></ul><p>​​语法：​​</p><p>ts 复制</p><p>import { unref } from &#39;vue&#39;; const value = unref(someRefOrValue);</p><p>​​2. 为什么需要 unref？​​ 在 Vue 3 的 Composition API 中，我们经常使用 ref 和 reactive 来管理状态。但有时候，我们不确定某个变量是 ref 还是普通值，这时 unref 可以 ​​统一处理​​，避免手动判断：</p><p>ts 复制</p><p>function useSomeLogic(maybeRef) { // 不用手动判断 maybeRef 是 ref 还是普通值 const value = unref(maybeRef); // 现在 value 一定是普通值}</p><p>​​3. 使用示例​​ ​​示例 1：处理可能是 ref 或普通值的参数​​</p><p>ts 复制</p><p>import { ref, unref } from &#39;vue&#39;; function double(numOrRef) { const num = unref(numOrRef); // 无论传入 ref 还是普通值，都能正确获取 return num * 2;} const count = ref(5);console.log(double(count)); // 10console.log(double(10)); // 20 ​​示例 2：在 watch 或 computed 中使用​​</p><p>ts 复制</p><p>import { ref, watch, unref } from &#39;vue&#39;; const count = ref(0); watch( () =&gt; unref(count), // 确保 watch 监听的总是普通值 (newValue) =&gt; { console.log(&#39;Count changed:&#39;, newValue); });</p><p>​​4. unref vs ref.value​​</p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>方式</strong></td><td><strong>适用场景</strong></td><td><strong>缺点</strong></td></tr><tr><td>unref(x)</td><td>适用于 ​​不确定 x 是 ref 还是普通值​​ 的情况</td><td>无</td></tr><tr><td>x.value</td><td>适用于 ​​明确知道 x 是 ref​​ 的情况</td><td>如果 x 不是 ref，会报错</td></tr></tbody></table><p>​​推荐​​：在 ​​工具函数​​ 或 ​​组合式函数​​ 中使用 unref，提高代码的健壮性。</p><p>​​5. 类似的方法​​</p><ul><li><p>​​toRef​​：将响应式对象的属性转换成 ref。</p></li><li><p>​​toValue​​（Vue 3.3+）：类似于 unref，但还能处理 getter 函数。</p></li><li><p>​​isRef​​：检查变量是否是 ref。 ​​总结​​</p></li><li><p>unref 是 Vue 3 提供的一个 ​​响应式工具函数​​，用于安全地获取 ref 或普通值。</p></li><li><p>适用于 ​​不确定变量是 ref 还是普通值​​ 的场景，避免手动 isRef 判断。</p></li><li><p>在 ​​组合式函数​​、​​工具函数​​ 或 ​​watch/computed​​ 中使用，使代码更健壮。</p></li></ul><p>如果你经常编写可复用的 Composition API 逻辑，unref 会非常有用！ 🚀 &gt; 来自 &lt;<a href="https://yuanbao.tencent.com/chat/naQivTmsDa/20453305-afb6-4fff-b4dd-5d8f46ca6e91" target="_blank" rel="noreferrer">https://yuanbao.tencent.com/chat/naQivTmsDa/20453305-afb6-4fff-b4dd-5d8f46ca6e91</a>&gt; &gt; 来自 &lt;<a href="https://yuanbao.tencent.com/chat/naQivTmsDa/20453305-afb6-4fff-b4dd-5d8f46ca6e91" target="_blank" rel="noreferrer">https://yuanbao.tencent.com/chat/naQivTmsDa/20453305-afb6-4fff-b4dd-5d8f46ca6e91</a>&gt;</p></div>',1)])])}const m=t(u,[["render",a]]);export{d as __pageData,m as default};
